import { describe, expect, test } from "bun:test";
import { tokenize } from "../src/parser.ts";

describe("tokenize", () => {
	test("keeps an escaped delimiter inside a quoted run", () => {
		expect(tokenize('"a\\"b"')).toEqual([{ kind: "string", value: 'a"b' }]);
	});
});

